//! Corpus Hub v2 — the types shared across crates.
//!
//! The hub serves PRE-INDEXED packs an agent pulls and queries, instead of a
//! JSON manifest it must clone and index locally (discussion #1374,
//! `docs/CORPUS_HUB_V2_IMPLEMENTATION.md`). Every type that crosses a crate
//! boundary or the network lives here so `xerj-hub`, `xerj-api`, `xerj-mcp`
//! and the CLI all speak one vocabulary.
//!
//! `xerj-common` depends on no other xerj crate, so this module holds only the
//! data shapes and the one renderer that turns an [`Answer`] into the text every
//! surface prints. The behaviour (download, verify, restore, route) is in
//! `xerj-hub`.
//!
//! Anything deserialized from the network carries `#[serde(deny_unknown_fields)]`
//! so a catalogue or a pack manifest from a future format version is refused
//! rather than half-read.

use serde::{Deserialize, Serialize};
use std::fmt::Write as _;

/// The catalogue shape this build writes. 2 adds optional `upstream`
/// (`owner/name` of the pack's git remote) on each entry. Readers still load
/// format 1 (that field is absent and reads as empty) so a cached catalogue
/// from before this field keeps working. A newer shape is refused.
/// See [`catalogue_format_supported`].
pub const CATALOGUE_FORMAT_VERSION: u32 = 2;
/// Oldest catalogue shape this build still loads.
pub const CATALOGUE_FORMAT_VERSION_MIN: u32 = 1;

/// True for a catalogue `format_version` this build can read.
pub fn catalogue_format_supported(version: u32) -> bool {
    (CATALOGUE_FORMAT_VERSION_MIN..=CATALOGUE_FORMAT_VERSION).contains(&version)
}

/// Bump when the pack archive layout changes. `format_version: 1` means the
/// snapshot layout (engine `create_snapshot`/`restore_snapshot`).
pub const PACK_FORMAT_VERSION: u32 = 1;

/// Where the catalogue and the hosted query API live.
pub const DEFAULT_HUB_URL: &str = "https://hub.xerj.org";

/// The hub's local root: `XERJ_HUB_HOME` when set and non-empty, else
/// `<home>/.xerj/hub` ([`crate::home::home_dir_from`]: `HOME`, else
/// `USERPROFILE`). `None` when neither is set.
///
/// This is THE rule. The CLI (`xerj hub pull`, which extracts packs under
/// `<root>/packs`) and the server (which, by default, lets a snapshot restore
/// read from that same `<root>/packs` — `limits.hub_pack_restore`) both resolve
/// it here, so a server started by the same user agrees with the CLI on where a
/// pulled pack lives.
pub fn hub_root_from(
    env: &dyn Fn(&str) -> Option<std::ffi::OsString>,
) -> Option<std::path::PathBuf> {
    if let Some(h) = env("XERJ_HUB_HOME").filter(|h| !h.is_empty()) {
        return Some(std::path::PathBuf::from(h));
    }
    crate::home::home_dir_from(env).map(|home| home.join(".xerj").join("hub"))
}

/// The directory `xerj hub pull` extracts verified packs into:
/// [`hub_root_from`]`/packs`, over the process environment.
pub fn hub_packs_dir() -> Option<std::path::PathBuf> {
    hub_root_from(&|key| std::env::var_os(key)).map(|root| root.join(HUB_PACKS_DIR))
}

/// The pack-cache directory name under the hub root.
pub const HUB_PACKS_DIR: &str = "packs";

/// Packs at or below this size are pulled automatically; larger ones are
/// answered through the hosted route until the user runs `xerj hub pull`.
pub const AUTO_PULL_MAX_BYTES: u64 = 50 * 1024 * 1024;

/// The local pack cache is pruned (least-recently-used) to stay under this.
pub const DISK_BUDGET_BYTES: u64 = 4 * 1024 * 1024 * 1024;

/// Hex of the ed25519 public key every hub catalogue and pack must verify
/// against: the public half of the `HUB_SIGNING_SEED` CI secret, derived from
/// it by `.github/workflows/hub-pubkey.yml` (run 38869497662, #1494).
///
/// It changes ONLY together with that secret. Rotating the seed without this
/// constant (or the other way round) makes every client refuse every pack;
/// `hub-packs.yml` and `hub-pubkey.yml` both compare the two and fail loudly on
/// a mismatch. Tests point the client at a throwaway key with the
/// `XERJ_HUB_PUBKEY` environment variable — see [`hub_pubkey`].
pub const HUB_PUBKEY_HEX: &str = "b68899321ec01ad8d0130d6e4790d9c75ffbc03bb0271f0a1522114c43562936";

/// The `XERJ_HUB_PUBKEY` value that makes this process behave as a build with
/// no hub key (tests only): the no-key paths stay reachable now that a real key
/// is compiled in. It can only take capability away — with no key every hub
/// surface refuses to fetch or extract anything, it never skips a check.
pub const HUB_PUBKEY_NONE: &str = "none";

/// The key to verify hub catalogues and packs with: a non-empty
/// `XERJ_HUB_PUBKEY` (tests) wins over the compiled-in [`HUB_PUBKEY_HEX`].
/// `None` means "this build cannot verify anything": the override is
/// [`HUB_PUBKEY_NONE`], or no key is compiled in. Callers refuse rather than
/// proceed unverified.
pub fn hub_pubkey() -> Option<String> {
    match std::env::var("XERJ_HUB_PUBKEY") {
        Ok(k) if k.trim().eq_ignore_ascii_case(HUB_PUBKEY_NONE) => None,
        Ok(k) if !k.trim().is_empty() => Some(k.trim().to_string()),
        _ => Some(HUB_PUBKEY_HEX.to_string()).filter(|k| !k.is_empty()),
    }
}

/// True when this build can verify hub catalogues and packs, i.e. when
/// [`hub_pubkey`] has a key: the compiled-in [`HUB_PUBKEY_HEX`], or a test
/// `XERJ_HUB_PUBKEY`. With `XERJ_HUB_PUBKEY=none` ([`HUB_PUBKEY_NONE`]) it is
/// false, and the hub surfaces (`xerj ask`, `xerj hub sync|pull`, the MCP hub
/// tools, `xerj init`'s hub skill) say plainly that the hub is unavailable
/// instead of failing on whatever the network returns.
pub fn hub_key_configured() -> bool {
    hub_pubkey().is_some()
}

/// What every hub surface says in a build with no hub key.
pub const NO_HUB_KEY_MESSAGE: &str = "Corpus Hub packs are not available in this build: it has \
     no hub signing key, so no catalogue or pack can be verified and nothing was downloaded. \
     For reference code, index the projects yourself with `xerj corpus add` and search them \
     with `xerj code` (see `xerj code --help`). A folder you indexed with `xerj autoindex` \
     is queried with `xerj search` or `xerj def`, not `xerj ask`.";

/// What a per-source licence review allows, straight from the registry's
/// `review.use`. Governs whether a pack is pulled silently, with a warning, or
/// never.
#[derive(Serialize, Deserialize, Clone, Copy, PartialEq, Eq, Debug)]
#[serde(rename_all = "kebab-case")]
pub enum LicenceClass {
    /// Public-domain, OGL, permissive — pull silently.
    AdaptWithAttribution,
    /// GPL/AGPL/SSPL/BUSL and the like — pull with a "read, do not copy" warning.
    ApproachOnly,
    /// Closed or non-redistributable — never pulled.
    Excluded,
}

/// One corpus as the catalogue lists it. The client picks a corpus from this
/// without downloading anything.
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(deny_unknown_fields)]
pub struct CatalogueEntry {
    pub slug: String,
    /// SEC, DB, NET, CRYPTO, WEB, API, OPS, LAW, HEALTH, AI, WRITE.
    pub domain: String,
    pub topics: Vec<String>,
    /// The registry's one-line "an agent working on ___ queries this for ___".
    pub ask_for: String,
    /// Upstream git repo as `owner/name` (the manifest's `repos[].url`, GitHub
    /// form). Several repos are joined with ", " (at most four). Empty on a
    /// catalogue written before this field, or when the manifest recorded no
    /// `owner/name` remote — never guessed from the slug.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub upstream: String,
    /// Full 40-hex commit the pack was built at.
    pub pin_sha: String,
    /// YYYY-MM-DD the pin was taken.
    pub pin_date: String,
    /// How often this corpus is re-pinned (7 for code, 1 for feeds).
    pub refresh_cadence_days: u32,
    pub licence_spdx: String,
    pub licence_class: LicenceClass,
    pub pack_bytes: u64,
    pub pack_url: String,
    pub pack_sha256: String,
    pub sig_url: String,
    /// crate / npm / go-module / pypi names this corpus answers for; used by the
    /// project-dependency router. Empty when none are recorded — never guessed.
    pub dependency_names: Vec<String>,
    /// e.g. "G7 4/5", or None. Never invented.
    pub quality_grade: Option<String>,
    pub term_sketch: Sketch,
}

/// A Bloom filter over a corpus's identifiers and vocabulary, used to route a
/// question to candidate corpora offline. See `xerj-hub`'s `sketch` module for
/// the hashing.
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(deny_unknown_fields)]
pub struct Sketch {
    pub m_bits: u32,
    pub k_hashes: u32,
    pub bits_base64: String,
}

/// The whole catalogue: one small signed file, refreshed in the background.
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(deny_unknown_fields)]
pub struct Catalogue {
    pub format_version: u32,
    /// RFC 3339.
    pub generated_at: String,
    pub corpora: Vec<CatalogueEntry>,
}

/// `pack.json` inside a pack archive.
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(deny_unknown_fields)]
pub struct PackManifest {
    pub format_version: u32,
    pub slug: String,
    pub pin_sha: String,
    pub pin_date: String,
    /// RFC 3339 the pack was built.
    pub built_at: String,
    /// `xerj --version` of the builder.
    pub builder_version: String,
    /// `xc-<slug>-b<build>`.
    pub index_prefix: String,
    /// Every index in the snapshot, the docs index and the defs index included.
    pub indices: Vec<PackIndex>,
    /// The name used with `create_snapshot`.
    pub snapshot_name: String,
    pub licence_spdx: String,
    pub licence_class: LicenceClass,
    /// Copied from the manifest's `repos[]`.
    pub sources: Vec<PackSource>,
    pub defs_count: u64,
    pub files_count: u64,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(deny_unknown_fields)]
pub struct PackIndex {
    pub name: String,
    pub docs: u64,
    pub bytes: u64,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(deny_unknown_fields)]
pub struct PackSource {
    pub repo: String,
    pub url: String,
    pub sha: String,
    pub licence: String,
}

/// One line of `defs.jsonl` and one document of the `-defs` index: a single
/// definition, with the literal value for constants and macros.
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct DefRecord {
    pub symbol: String,
    /// As `extract/code.rs` names it: function, const, define, struct, …
    pub kind: String,
    pub lang: String,
    /// Path relative to the corpus root, forward slashes.
    pub file: String,
    /// 1-based line the NAME sits on.
    pub line: u32,
    /// The declaration, signature only, at most 400 chars.
    pub text: String,
    /// The literal value for constants/macros/defines; None otherwise.
    pub value: Option<String>,
}

/// Where an answer came from.
#[derive(Serialize, Deserialize, Clone, Copy, PartialEq, Eq, Debug)]
#[serde(rename_all = "snake_case")]
pub enum AnsweredFrom {
    /// A pack already on this machine.
    LocalPack,
    /// The hub's hosted query node.
    Hosted,
    /// A corpus indexed locally the old way (not a hub pack).
    LocalIndex,
}

/// Which shape of question this answer is.
#[derive(Serialize, Deserialize, Clone, Copy, PartialEq, Eq, Debug)]
#[serde(rename_all = "snake_case")]
pub enum AnswerMode {
    /// One definition, with its value.
    Def,
    /// Ranked passages for a how-does-it-work question.
    How,
    /// The file list with per-path licence.
    Files,
}

/// One retrieved definition or passage.
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(deny_unknown_fields)]
pub struct Hit {
    pub file: String,
    pub line: u32,
    pub kind: String,
    pub text: String,
    pub value: Option<String>,
    pub score: f32,
    /// Set for an approach-only source, naming the licence.
    pub licence_warning: Option<String>,
}

/// What every surface returns: the CLI (as `--json`), the MCP tools and the
/// hosted HTTP endpoints all build this and render it with [`render`].
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(deny_unknown_fields)]
pub struct Answer {
    pub corpus: String,
    pub pin_sha: String,
    pub pin_date: String,
    pub age_days: u32,
    pub licence_spdx: String,
    pub licence_class: LicenceClass,
    pub answered_from: AnsweredFrom,
    pub mode: AnswerMode,
    pub hits: Vec<Hit>,
    pub truncated: bool,
    /// One line each, e.g. "pin is 23 days old; the question asks for the current source".
    pub warnings: Vec<String>,
}

impl AnsweredFrom {
    /// The words printed on the `answered from:` line.
    pub fn label(self) -> &'static str {
        match self {
            AnsweredFrom::LocalPack => "local pack",
            AnsweredFrom::Hosted => "hosted hub",
            AnsweredFrom::LocalIndex => "local index",
        }
    }
}

/// Render an [`Answer`] to the text every surface prints. The format is fixed by
/// `docs/CORPUS_HUB_V2_IMPLEMENTATION.md` §1:
///
/// ```text
/// <corpus>  pin <pin_date> (<age_days> day[s] old)  <licence_spdx>  <file>:<line>
/// <text>
/// [value: <value>]            # only in def mode when value is Some
/// answered from: <local pack|hosted hub|local index>
/// [warning: …]                # one line per warning
/// ```
///
/// For several hits the first lines repeat per hit; the `answered from:` line is
/// printed once at the end. With no hits a single line states the corpus and pin.
pub fn render(answer: &Answer) -> String {
    let age = if answer.age_days == 1 {
        "1 day old".to_string()
    } else {
        format!("{} days old", answer.age_days)
    };
    let header_prefix = format!(
        "{}  pin {} ({})  {}",
        answer.corpus, answer.pin_date, age, answer.licence_spdx
    );

    let mut out = String::new();
    if answer.hits.is_empty() {
        let _ = write!(
            out,
            "{header_prefix}\nno match in {} (pin {})",
            answer.corpus, answer.pin_date
        );
    } else {
        for hit in &answer.hits {
            let _ = write!(
                out,
                "{header_prefix}  {}:{}\n{}",
                hit.file, hit.line, hit.text
            );
            if answer.mode == AnswerMode::Def {
                if let Some(v) = &hit.value {
                    let _ = write!(out, "\nvalue: {v}");
                }
            }
            if let Some(w) = &hit.licence_warning {
                let _ = write!(out, "\n  {w}");
            }
            out.push('\n');
        }
        out.pop(); // drop the trailing newline before the footer
    }

    let _ = write!(out, "\nanswered from: {}", answer.answered_from.label());
    for w in &answer.warnings {
        let _ = write!(out, "\nwarning: {w}");
    }
    out
}

#[cfg(test)]
mod tests {
    fn hub_env<'a>(
        vars: &'a [(&'a str, &'a str)],
    ) -> impl Fn(&str) -> Option<std::ffi::OsString> + 'a {
        move |key| {
            vars.iter()
                .find(|(k, _)| *k == key)
                .map(|(_, v)| std::ffi::OsString::from(v))
        }
    }

    #[test]
    fn the_hub_root_rule_is_xerj_hub_home_then_home_then_nothing() {
        use std::path::PathBuf;
        assert_eq!(
            hub_root_from(&hub_env(&[
                ("XERJ_HUB_HOME", "/srv/hub"),
                ("HOME", "/home/u")
            ])),
            Some(PathBuf::from("/srv/hub"))
        );
        assert_eq!(
            hub_root_from(&hub_env(&[("XERJ_HUB_HOME", ""), ("HOME", "/home/u")])),
            Some(PathBuf::from("/home/u/.xerj/hub"))
        );
        assert_eq!(
            hub_root_from(&hub_env(&[("USERPROFILE", "/Users/u")])),
            Some(PathBuf::from("/Users/u/.xerj/hub"))
        );
        // No home at all: the server grants nothing (never `./.xerj/hub`).
        assert_eq!(hub_root_from(&hub_env(&[])), None);
    }

    use super::*;
    use serde_json::json;

    #[test]
    fn a_build_without_a_hub_key_points_ask_at_local_search() {
        assert!(NO_HUB_KEY_MESSAGE.contains("`xerj search`"));
        assert!(NO_HUB_KEY_MESSAGE.contains("`xerj def`"));
        assert!(NO_HUB_KEY_MESSAGE.contains("`xerj autoindex`"));
        assert!(NO_HUB_KEY_MESSAGE.contains("not `xerj ask`"));
        assert!(!NO_HUB_KEY_MESSAGE.contains("xerj hub sync"));
    }

    #[test]
    fn the_compiled_in_hub_key_is_32_bytes_of_lower_hex() {
        // The workflows read it with a `[0-9a-fA-F]*` sed and compare lower-case;
        // ed25519.sh and verify_bytes both want exactly 64 hex characters.
        assert_eq!(HUB_PUBKEY_HEX.len(), 64, "{HUB_PUBKEY_HEX}");
        assert!(
            HUB_PUBKEY_HEX
                .bytes()
                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)),
            "{HUB_PUBKEY_HEX}"
        );
    }

    #[test]
    fn the_hub_key_stays_on_the_one_line_the_workflows_read() {
        // hub-packs.yml and hub-pubkey.yml extract the key with a single-line
        // sed over this file. If a reformat ever wrapped the declaration, they
        // would read "" and go quietly dormant instead of publishing.
        let line = format!("\npub const HUB_PUBKEY_HEX: &str = \"{HUB_PUBKEY_HEX}\";\n");
        assert!(
            include_str!("hub.rs").replace("\r\n", "\n").contains(&line),
            "{line}"
        );
    }

    #[test]
    fn licence_class_is_kebab_case() {
        assert_eq!(
            serde_json::to_value(LicenceClass::AdaptWithAttribution).unwrap(),
            json!("adapt-with-attribution")
        );
        assert_eq!(
            serde_json::to_value(LicenceClass::ApproachOnly).unwrap(),
            json!("approach-only")
        );
        assert_eq!(
            serde_json::to_value(LicenceClass::Excluded).unwrap(),
            json!("excluded")
        );
        let c: LicenceClass = serde_json::from_value(json!("approach-only")).unwrap();
        assert_eq!(c, LicenceClass::ApproachOnly);
    }

    #[test]
    fn answered_from_and_mode_are_snake_case() {
        assert_eq!(
            serde_json::to_value(AnsweredFrom::LocalPack).unwrap(),
            json!("local_pack")
        );
        assert_eq!(
            serde_json::to_value(AnsweredFrom::Hosted).unwrap(),
            json!("hosted")
        );
        assert_eq!(
            serde_json::to_value(AnsweredFrom::LocalIndex).unwrap(),
            json!("local_index")
        );
        assert_eq!(serde_json::to_value(AnswerMode::Def).unwrap(), json!("def"));
        assert_eq!(serde_json::to_value(AnswerMode::How).unwrap(), json!("how"));
        assert_eq!(
            serde_json::to_value(AnswerMode::Files).unwrap(),
            json!("files")
        );
    }

    fn sample_entry() -> CatalogueEntry {
        CatalogueEntry {
            slug: "lz4".into(),
            domain: "NET".into(),
            topics: vec!["compression".into()],
            ask_for: "fast block compression".into(),
            upstream: "lz4/lz4".into(),
            pin_sha: "0774d05537f9762f838f7ab541b7765f1a729cb5".into(),
            pin_date: "2026-10-02".into(),
            refresh_cadence_days: 7,
            licence_spdx: "BSD-2-Clause".into(),
            licence_class: LicenceClass::AdaptWithAttribution,
            pack_bytes: 2_000_000,
            pack_url: "https://example/lz4.hubpack.tar.zst".into(),
            pack_sha256: "deadbeef".into(),
            sig_url: "https://example/lz4.hubpack.tar.zst.sig".into(),
            dependency_names: vec!["lz4".into()],
            quality_grade: None,
            term_sketch: Sketch {
                m_bits: 64,
                k_hashes: 7,
                bits_base64: "AAAAAAAAAAA=".into(),
            },
        }
    }

    #[test]
    fn catalogue_round_trips() {
        let cat = Catalogue {
            format_version: CATALOGUE_FORMAT_VERSION,
            generated_at: "2026-10-14T00:00:00Z".into(),
            corpora: vec![sample_entry()],
        };
        let s = serde_json::to_string(&cat).unwrap();
        let back: Catalogue = serde_json::from_str(&s).unwrap();
        assert_eq!(back.corpora.len(), 1);
        assert_eq!(back.corpora[0].slug, "lz4");
        assert_eq!(back.corpora[0].upstream, "lz4/lz4");
        assert_eq!(
            back.corpora[0].licence_class,
            LicenceClass::AdaptWithAttribution
        );
    }

    /// A catalogue written before `upstream` existed has no such key. It still
    /// loads, and the field is empty rather than invented from the slug.
    #[test]
    fn a_catalogue_entry_without_upstream_loads_as_empty() {
        let mut cat = Catalogue {
            format_version: CATALOGUE_FORMAT_VERSION_MIN,
            generated_at: "2026-10-14T00:00:00Z".into(),
            corpora: vec![sample_entry()],
        };
        cat.corpora[0].upstream.clear();
        let mut v = serde_json::to_value(&cat).unwrap();
        v["corpora"][0].as_object_mut().unwrap().remove("upstream");
        let back: Catalogue = serde_json::from_value(v).unwrap();
        assert_eq!(back.corpora[0].upstream, "");
        assert_eq!(back.corpora[0].slug, "lz4");
        assert!(catalogue_format_supported(CATALOGUE_FORMAT_VERSION_MIN));
        assert!(catalogue_format_supported(CATALOGUE_FORMAT_VERSION));
        assert!(!catalogue_format_supported(0));
        assert!(!catalogue_format_supported(CATALOGUE_FORMAT_VERSION + 1));
    }

    #[test]
    fn unknown_field_is_refused() {
        // A catalogue entry with a field this version does not know is rejected,
        // not half-read.
        let mut v = serde_json::to_value(sample_entry()).unwrap();
        v["surprise"] = json!(1);
        let r: Result<CatalogueEntry, _> = serde_json::from_value(v);
        assert!(
            r.is_err(),
            "deny_unknown_fields should reject an extra field"
        );
    }

    #[test]
    fn def_record_round_trips_with_and_without_value() {
        let with = DefRecord {
            symbol: "LZ4_VERSION_RELEASE".into(),
            kind: "define".into(),
            lang: "c".into(),
            file: "lib/lz4.h".into(),
            line: 133,
            text: "#define LZ4_VERSION_RELEASE  0".into(),
            value: Some("0".into()),
        };
        let back: DefRecord = serde_json::from_str(&serde_json::to_string(&with).unwrap()).unwrap();
        assert_eq!(back, with);
        let without = DefRecord {
            value: None,
            ..with
        };
        let back: DefRecord =
            serde_json::from_str(&serde_json::to_string(&without).unwrap()).unwrap();
        assert_eq!(back.value, None);
    }

    fn answer_with(
        mode: AnswerMode,
        hits: Vec<Hit>,
        from: AnsweredFrom,
        warnings: Vec<String>,
    ) -> Answer {
        Answer {
            corpus: "lz4".into(),
            pin_sha: "0774d05537f9762f838f7ab541b7765f1a729cb5".into(),
            pin_date: "2026-10-02".into(),
            age_days: 1,
            licence_spdx: "BSD-2-Clause".into(),
            licence_class: LicenceClass::AdaptWithAttribution,
            answered_from: from,
            mode,
            hits,
            truncated: false,
            warnings,
        }
    }

    #[test]
    fn render_one_def_hit() {
        let a = answer_with(
            AnswerMode::Def,
            vec![Hit {
                file: "lib/lz4.h".into(),
                line: 133,
                kind: "define".into(),
                text: "#define LZ4_VERSION_RELEASE  0".into(),
                value: Some("0".into()),
                score: 14.5,
                licence_warning: None,
            }],
            AnsweredFrom::LocalPack,
            vec![],
        );
        let expected = "lz4  pin 2026-10-02 (1 day old)  BSD-2-Clause  lib/lz4.h:133\n\
                        #define LZ4_VERSION_RELEASE  0\n\
                        value: 0\n\
                        answered from: local pack";
        assert_eq!(render(&a), expected);
    }

    #[test]
    fn render_three_hits_how_mode_with_warning() {
        let hit = |f: &str, l: u32| Hit {
            file: f.into(),
            line: l,
            kind: "function".into(),
            text: format!("fn at {f}"),
            value: None,
            score: 1.0,
            licence_warning: None,
        };
        let a = answer_with(
            AnswerMode::How,
            vec![hit("a.rs", 1), hit("b.rs", 2), hit("c.rs", 3)],
            AnsweredFrom::Hosted,
            vec!["pin is 23 days old; the question asks for the current source".into()],
        );
        let expected = "lz4  pin 2026-10-02 (1 day old)  BSD-2-Clause  a.rs:1\n\
                        fn at a.rs\n\
                        lz4  pin 2026-10-02 (1 day old)  BSD-2-Clause  b.rs:2\n\
                        fn at b.rs\n\
                        lz4  pin 2026-10-02 (1 day old)  BSD-2-Clause  c.rs:3\n\
                        fn at c.rs\n\
                        answered from: hosted hub\n\
                        warning: pin is 23 days old; the question asks for the current source";
        assert_eq!(render(&a), expected);
    }

    #[test]
    fn render_no_hits() {
        let a = answer_with(AnswerMode::Def, vec![], AnsweredFrom::LocalPack, vec![]);
        let expected = "lz4  pin 2026-10-02 (1 day old)  BSD-2-Clause\n\
                        no match in lz4 (pin 2026-10-02)\n\
                        answered from: local pack";
        assert_eq!(render(&a), expected);
    }

    #[test]
    fn age_days_pluralization() {
        let a = answer_with(AnswerMode::Def, vec![], AnsweredFrom::LocalPack, vec![]);
        assert!(render(&a).contains("(1 day old)"));
        let mut a2 = a;
        a2.age_days = 5;
        assert!(render(&a2).contains("(5 days old)"));
    }
}

//! `xerj hub build-catalogue`: the signed catalogue clients route and pull from
//! (docs/CORPUS_HUB_V2_IMPLEMENTATION.md §4).
//!
//! One [`CatalogueEntry`] per LIVE lane-A corpus in `backlog/backlog-100.json`
//! whose CURRENT pin (the manifest's first repo sha) has a pack in `--packs`.
//! The entry's fields come from the registry manifest (through
//! [`crate::catalogue::build_catalogue`], the one manifest parser), the backlog
//! row (domain, refresh cadence, the `ask_for` fallback) and the pack itself
//! (bytes, sha256, the definitions and paths for the term sketch).
//!
//! Every pack is checked before it is listed: whole-archive sha256, the detached
//! signature against the key clients embed, `format_version`, and that its
//! `pack.json` names this slug at this pin. A pack that fails is a hard error,
//! never a silent omission: a catalogue is a complete snapshot, so a dropped
//! entry would delist a corpus. The finished catalogue's own signature is
//! verified against the same key before the command succeeds, so a seed that
//! is not the private half of [`xerj_common::hub::HUB_PUBKEY_HEX`] fails here
//! instead of publishing a catalogue no client can load.
//!
//! Live lane-B corpora (record packs, `build-pack --from-pack`) have no
//! registry manifest and no commit pin: their entry comes from the backlog row
//! and the pack's own signed `pack.json`, and their current pin is the newest
//! verified pack for the slug in `--packs` (see [`record_entries`]).
//!
//! `quality_grade` comes only from the graded G7 suites in
//! `<registry>/backlog/*graded*.json`, read exactly as the hub site generator
//! reads them (`tools/corpus-hub-site/gen.py` `parse_graded_suites` and
//! `g7_badge`), so the catalogue and the corpus page show the same grade. A
//! lane-A corpus with no graded suite gets `None`, and a lane-B record pack
//! always does: the field's contract is "never invent one" (see
//! [`read_graded_suites`]).

use std::collections::{BTreeMap, HashSet};
use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};

use anyhow::{anyhow, bail, Context, Result};
use serde_json::Value;
use sha2::{Digest, Sha256};

use xerj_autoindex::harvest::sign::{sign_bytes, verify_bytes};
use xerj_common::hub::{
    Catalogue, CatalogueEntry, DefRecord, LicenceClass, PackManifest, PACK_FORMAT_VERSION,
};

use crate::catalogue::{build_catalogue, canonical_json, CorpusBuildInput};
use crate::pack::PackFileEntry;

/// Where published packs live unless `--release-base` says otherwise. The plan's
/// `pack_url` is `<this>/pack-<slug>-<pin8>/<slug>-<pin8>.hubpack.tar.zst`.
pub const DEFAULT_RELEASE_BASE: &str = "https://github.com/xerj-org/xerj/releases/download";

/// `refresh` class → `refresh_cadence_days` (plan §1: 7 for code, 1 for feeds).
/// The same table as `tools/hub-packs/hub_packs.py` `CADENCE_DAYS`.
fn cadence_days(refresh: &str) -> u32 {
    match refresh {
        "daily" => 1,
        _ => 7,
    }
}

const USAGE: &str = "usage: xerj hub build-catalogue --registry <dir> --packs <dir> --out <file> --sign-key <seed-file>
                                  [--backlog <file>] [--release-base <url>] [--tags <tsv>]

Builds and signs the hub catalogue (writes <out> and <out>.sig) from the packs in
--packs (`<slug>-<pin8>.hubpack.tar.zst` + `.sig`, as `hub build-pack --out` writes
them). One entry per live lane-A corpus in the backlog (default
<registry>/backlog/backlog-100.json) whose current pin has a pack there.

  --release-base <url>  pack_url prefix (default
                        https://github.com/xerj-org/xerj/releases/download)
  --tags <tsv>          `slug<TAB>pin8<TAB>tag` lines naming each pack's release
                        tag (a -rN retag); default tag pack-<slug>-<pin8>

Every pack is verified (sha256, signature against the hub key this build embeds,
format, slug and pin) before it is listed; any failure aborts.

quality_grade comes from the graded G7 suites in <registry>/backlog/*graded*.json
(the files the hub site reads); a corpus with no graded suite has none.";

/// Inputs to [`build`]. Paths as given on the command line.
pub struct Options {
    pub registry: PathBuf,
    pub backlog: PathBuf,
    pub packs: PathBuf,
    pub release_base: String,
    /// `(slug, pin8) -> release tag`, from `--tags`.
    pub tags: BTreeMap<(String, String), String>,
    /// RFC 3339; the CLI passes now.
    pub generated_at: String,
}

/// What [`build`] produced.
pub struct Built {
    pub catalogue: Catalogue,
    /// The exact bytes to write to `catalogue.json`.
    pub bytes: Vec<u8>,
    /// Hex ed25519 signature over `bytes`.
    pub sig_hex: String,
    /// Live corpora with no pack for their current pin in `--packs`.
    pub without_pack: Vec<String>,
    /// Archives in `--packs` that matched no live corpus's current pin.
    pub unmatched: Vec<String>,
}

/// `xerj hub build-catalogue …`.
pub fn run(args: &[String]) -> i32 {
    let mut registry: Option<String> = None;
    let mut backlog: Option<String> = None;
    let mut packs: Option<String> = None;
    let mut out: Option<String> = None;
    let mut sign_key: Option<String> = None;
    let mut release_base: Option<String> = None;
    let mut tags: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let flag = args[i].as_str();
        if matches!(flag, "-h" | "--help") {
            println!("{USAGE}");
            return 0;
        }
        let slot = match flag {
            "--registry" => &mut registry,
            "--backlog" => &mut backlog,
            "--packs" => &mut packs,
            "--out" => &mut out,
            "--sign-key" => &mut sign_key,
            "--release-base" => &mut release_base,
            "--tags" => &mut tags,
            other => {
                eprintln!("xerj hub build-catalogue: unexpected argument '{other}'\n\n{USAGE}");
                return 2;
            }
        };
        match args.get(i + 1) {
            Some(v) => *slot = Some(v.clone()),
            None => {
                eprintln!("xerj hub build-catalogue: {flag} needs a value\n\n{USAGE}");
                return 2;
            }
        }
        i += 2;
    }
    let (Some(registry), Some(packs), Some(out), Some(sign_key)) = (registry, packs, out, sign_key)
    else {
        eprintln!(
            "xerj hub build-catalogue: --registry, --packs, --out and --sign-key are all \
             required\n\n{USAGE}"
        );
        return 2;
    };
    match run_inner(
        &registry,
        backlog.as_deref(),
        &packs,
        &out,
        &sign_key,
        release_base.as_deref(),
        tags.as_deref(),
    ) {
        Ok(line) => {
            println!("{line}");
            0
        }
        Err(e) => {
            eprintln!("xerj hub build-catalogue: {e:#}");
            1
        }
    }
}

fn run_inner(
    registry: &str,
    backlog: Option<&str>,
    packs: &str,
    out: &str,
    sign_key_file: &str,
    release_base: Option<&str>,
    tags: Option<&str>,
) -> Result<String> {
    let seed = fs::read_to_string(sign_key_file)
        .with_context(|| format!("read sign key {sign_key_file}"))?
        .trim()
        .to_string();
    let pubkey = xerj_common::hub::hub_pubkey().ok_or_else(|| {
        anyhow!(
            "this build has no hub public key, so neither the packs nor the catalogue can be \
             verified; refusing to build"
        )
    })?;
    let registry = PathBuf::from(registry);
    let opts = Options {
        backlog: backlog
            .map(PathBuf::from)
            .unwrap_or_else(|| registry.join("backlog").join("backlog-100.json")),
        registry,
        packs: PathBuf::from(packs),
        release_base: release_base.unwrap_or(DEFAULT_RELEASE_BASE).to_string(),
        tags: match tags {
            Some(p) => read_tags(Path::new(p))?,
            None => BTreeMap::new(),
        },
        generated_at: chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
    };
    let built = build(&opts, &seed, &pubkey)?;
    for slug in &built.unmatched {
        eprintln!("xerj hub build-catalogue: note: {slug} matches no live corpus's current pin; not listed");
    }
    let out = PathBuf::from(out);
    fs::write(&out, &built.bytes).with_context(|| format!("write {}", out.display()))?;
    let mut sig = out.clone().into_os_string();
    sig.push(".sig");
    fs::write(&sig, built.sig_hex.as_bytes())
        .with_context(|| format!("write {}", PathBuf::from(&sig).display()))?;
    Ok(format!(
        "catalogue {} corpora, {} bytes ({} live corpora have no pack yet)",
        built.catalogue.corpora.len(),
        built.bytes.len(),
        built.without_pack.len()
    ))
}

/// `slug<TAB>pin8<TAB>tag` lines (the `fetch-list` output of
/// `tools/hub-packs/hub_packs.py`). Blank lines are skipped; anything else
/// malformed is an error.
pub fn read_tags(path: &Path) -> Result<BTreeMap<(String, String), String>> {
    let text = fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
    let mut map = BTreeMap::new();
    for (n, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split('\t').map(str::trim).collect();
        let [slug, pin8, tag] = parts[..] else {
            bail!(
                "{}:{}: expected slug<TAB>pin8<TAB>tag",
                path.display(),
                n + 1
            );
        };
        map.insert((slug.to_string(), pin8.to_string()), tag.to_string());
    }
    Ok(map)
}

/// Build and sign the catalogue. `pubkey_hex` is the key clients embed: every
/// pack and the finished catalogue must verify under it.
pub fn build(opts: &Options, seed_hex: &str, pubkey_hex: &str) -> Result<Built> {
    let backlog: Value = serde_json::from_str(
        &fs::read_to_string(&opts.backlog)
            .with_context(|| format!("read backlog {}", opts.backlog.display()))?,
    )
    .with_context(|| format!("parse backlog {}", opts.backlog.display()))?;
    let rows = backlog
        .get("corpora")
        .and_then(Value::as_array)
        .ok_or_else(|| anyhow!("backlog {} has no corpora[]", opts.backlog.display()))?;

    let grades = read_graded_suites(&opts.registry.join("backlog"))?;
    let mut inputs: Vec<CorpusBuildInput> = Vec::new();
    let mut without_pack: Vec<String> = Vec::new();
    let mut used: HashSet<String> = HashSet::new();
    for row in rows {
        let field = |k: &str| row.get(k).and_then(Value::as_str).unwrap_or("");
        if field("status") != "live" || field("lane") != "A" {
            continue;
        }
        let slug = field("slug");
        let manifest_path = opts.registry.join(format!("{slug}.json"));
        if !manifest_path.is_file() {
            // `hub_packs.py plan` warns about these; there is no pack to list.
            without_pack.push(slug.to_string());
            continue;
        }
        let manifest: Value = serde_json::from_str(
            &fs::read_to_string(&manifest_path)
                .with_context(|| format!("read {}", manifest_path.display()))?,
        )
        .with_context(|| format!("parse {}", manifest_path.display()))?;
        let pin_sha = manifest
            .pointer("/repos/0/sha")
            .and_then(Value::as_str)
            .unwrap_or("")
            .trim()
            .to_string();
        if pin_sha.len() != 40 || !pin_sha.chars().all(|c| c.is_ascii_hexdigit()) {
            bail!(
                "{}: repos[0].sha is not a 40-hex commit",
                manifest_path.display()
            );
        }
        let pin8 = &pin_sha[..8];
        let file = format!("{slug}-{pin8}.hubpack.tar.zst");
        let archive = opts.packs.join(&file);
        if !archive.is_file() {
            without_pack.push(slug.to_string());
            continue;
        }
        used.insert(file.clone());

        let pack = read_pack(&archive, pubkey_hex)
            .with_context(|| format!("pack {}", archive.display()))?;
        if pack.manifest.slug != slug {
            bail!(
                "{file}: pack.json names slug '{}', not '{slug}'",
                pack.manifest.slug
            );
        }
        if !pack.manifest.pin_sha.eq_ignore_ascii_case(&pin_sha) {
            bail!(
                "{file}: pack.json pin {} is not the manifest's pin {pin_sha}",
                pack.manifest.pin_sha
            );
        }

        // Terms (plan §4): every definition symbol, every path component without
        // extension, every lower-case 3+ letter word of ask_for and topics. Raw
        // and lower-cased, because the router probes both forms of each token.
        let mut terms: Vec<String> = Vec::new();
        let mut push = |t: &str| {
            if !t.is_empty() {
                terms.push(t.to_string());
                terms.push(t.to_lowercase());
            }
        };
        for d in &pack.defs {
            push(&d.symbol);
        }
        for f in &pack.files {
            for comp in f.path.split('/') {
                push(strip_extension(comp));
            }
        }
        let backlog_domain = field("domain");
        let ask_for = [
            manifest.get("ask_for").and_then(Value::as_str),
            manifest.get("domain").and_then(Value::as_str),
            Some(backlog_domain),
        ]
        .into_iter()
        .flatten()
        .map(str::trim)
        .find(|s| !s.is_empty())
        .unwrap_or("");
        let topics: Vec<&str> = manifest
            .get("topics")
            .and_then(Value::as_array)
            .map(|a| a.iter().filter_map(Value::as_str).collect())
            .unwrap_or_default();
        for text in std::iter::once(ask_for).chain(topics) {
            for w in words(text) {
                terms.push(w);
            }
        }

        let tag = opts
            .tags
            .get(&(slug.to_string(), pin8.to_string()))
            .cloned()
            .unwrap_or_else(|| format!("pack-{slug}-{pin8}"));
        let pack_url = format!("{}/{tag}/{file}", opts.release_base.trim_end_matches('/'));
        inputs.push(CorpusBuildInput {
            manifest_path,
            domain: field("cat").to_string(),
            refresh_cadence_days: cadence_days(field("refresh")),
            pack_bytes: pack.bytes,
            sig_url: format!("{pack_url}.sig"),
            pack_url,
            pack_sha256: pack.sha256,
            quality_grade: grades.get(slug).cloned(),
            terms,
            pin_sha,
            ask_for: backlog_domain.to_string(),
        });
    }
    let records = record_entries(opts, rows, pubkey_hex, &mut used, &mut without_pack)?;
    if inputs.is_empty() && records.is_empty() {
        bail!(
            "no live corpus has a pack for its current pin in {}",
            opts.packs.display()
        );
    }

    let mut unmatched: Vec<String> = Vec::new();
    for entry in
        fs::read_dir(&opts.packs).with_context(|| format!("list {}", opts.packs.display()))?
    {
        let name = entry?.file_name().to_string_lossy().into_owned();
        if name.ends_with(".hubpack.tar.zst") && !used.contains(&name) {
            unmatched.push(name);
        }
    }
    unmatched.sort();

    let (mut catalogue, mut sig_hex) = build_catalogue(&inputs, &opts.generated_at, seed_hex)?;
    if !records.is_empty() {
        catalogue.corpora.extend(records);
        catalogue.corpora.sort_by(|a, b| a.slug.cmp(&b.slug));
        sig_hex = sign_bytes(&canonical_json(&catalogue)?, seed_hex).context("sign catalogue")?;
    }
    let bytes = canonical_json(&catalogue)?;
    verify_bytes(&bytes, &sig_hex, pubkey_hex).context(
        "the catalogue's signature does not verify under the hub key this build embeds: the \
         signing seed is not its private half, and no client could load this catalogue",
    )?;
    Ok(Built {
        catalogue,
        bytes,
        sig_hex,
        without_pack,
        unmatched,
    })
}

/// `slug -> "G7 <median>/5"` from every `*graded*.json` in `backlog_dir`, the
/// files and rules of the site generator (`tools/corpus-hub-site/gen.py`):
///
/// - files in sorted name order; a later file's suite for a slug replaces an
///   earlier one (`out[slug] = suite`);
/// - the suites map is the first of `graded`, `suites`, `corpora` present; a
///   file whose map is not an object (e.g. `"graded": "<date>"`) or that is
///   not valid JSON is skipped;
/// - only suites that carry `queries` count;
/// - the suite's own `median` when it has one, else `suite_median`: per
///   query `verdict` (falling back to `grade`), pass/relevant = 1,
///   partial = 0.5, anything else 0, `*excluded*` left out of both sides,
///   scaled to 5;
/// - rendered `G7 {:.1}/5`, the site badge's text.
///
/// One deliberate difference: where the site would print `0.0/5` for a suite
/// with no gradable query (or a `median` that is not a number), this returns
/// no grade, because nothing was graded there.
pub fn read_graded_suites(backlog_dir: &Path) -> Result<BTreeMap<String, String>> {
    let mut files: Vec<PathBuf> = Vec::new();
    match fs::read_dir(backlog_dir) {
        Ok(rd) => {
            for entry in rd {
                let path = entry
                    .with_context(|| format!("list {}", backlog_dir.display()))?
                    .path();
                let name = path
                    .file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_default();
                if name.contains("graded") && name.ends_with(".json") && path.is_file() {
                    files.push(path);
                }
            }
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(BTreeMap::new()),
        Err(e) => return Err(e).with_context(|| format!("list {}", backlog_dir.display())),
    }
    files.sort();
    let mut out = BTreeMap::new();
    for path in files {
        let text = fs::read_to_string(&path).with_context(|| format!("read {}", path.display()))?;
        let Ok(data) = serde_json::from_str::<Value>(&text) else {
            continue;
        };
        let Some(container) = ["graded", "suites", "corpora"]
            .into_iter()
            .find_map(|k| data.get(k))
        else {
            continue;
        };
        let Some(suites) = container.as_object() else {
            continue;
        };
        for (slug, suite) in suites {
            let Some(queries) = suite.get("queries") else {
                continue;
            };
            let median = match suite.get("median") {
                None | Some(Value::Null) => suite_median(queries),
                Some(v) => v.as_f64(),
            };
            match median {
                Some(m) => out.insert(slug.clone(), format!("G7 {m:.1}/5")),
                None => out.remove(slug),
            };
        }
    }
    Ok(out)
}

/// One entry per LIVE lane-B corpus (a record pack built by `hub build-pack
/// --from-pack`) with a pack in `--packs`. A record pack's pin is a content
/// pin, not a registry fact, so its current pack is the newest one for the
/// slug in `--packs` (by `pack.json` `built_at`); the catalogue job downloads
/// the record packs' published releases for it to choose from. Every candidate
/// is verified like a lane-A pack; a failure aborts. Fields: slug, pin, licence
/// and sources from the signed `pack.json`; domain, refresh, `ask_for` and
/// `topics` from the backlog row.
fn record_entries(
    opts: &Options,
    rows: &[Value],
    pubkey_hex: &str,
    used: &mut HashSet<String>,
    without_pack: &mut Vec<String>,
) -> Result<Vec<CatalogueEntry>> {
    let mut names: Vec<String> = Vec::new();
    for entry in
        fs::read_dir(&opts.packs).with_context(|| format!("list {}", opts.packs.display()))?
    {
        names.push(entry?.file_name().to_string_lossy().into_owned());
    }
    names.sort();
    let mut out = Vec::new();
    for row in rows {
        let field = |k: &str| row.get(k).and_then(Value::as_str).unwrap_or("");
        if field("status") != "live" || field("lane") != "B" {
            continue;
        }
        let slug = field("slug");
        let mut best: Option<(String, PackFacts)> = None;
        for name in &names {
            let Some(pin8) = name
                .strip_prefix(&format!("{slug}-"))
                .and_then(|r| r.strip_suffix(".hubpack.tar.zst"))
            else {
                continue;
            };
            if pin8.len() != 8 || !pin8.chars().all(|c| matches!(c, '0'..='9' | 'a'..='f')) {
                continue;
            }
            let pack = read_pack(&opts.packs.join(name), pubkey_hex)
                .with_context(|| format!("pack {name}"))?;
            if pack.manifest.slug != slug {
                bail!(
                    "{name}: pack.json names slug '{}', not '{slug}'",
                    pack.manifest.slug
                );
            }
            if !pack.manifest.pin_sha.starts_with(pin8) {
                bail!(
                    "{name}: pack.json pin {} does not start with the file's {pin8}",
                    pack.manifest.pin_sha
                );
            }
            used.insert(name.clone());
            let newer = match &best {
                Some((_, b)) => pack.manifest.built_at > b.manifest.built_at,
                None => true,
            };
            if newer {
                best = Some((name.clone(), pack));
            }
        }
        let Some((file, pack)) = best else {
            without_pack.push(slug.to_string());
            continue;
        };
        if pack.manifest.licence_class == LicenceClass::Excluded {
            // Plan §12.1: an excluded licence gets no listing.
            continue;
        }
        let pin8 = &pack.manifest.pin_sha[..8];
        let ask_for = field("domain").trim().to_string();
        let topics: Vec<String> = row
            .pointer("/tags/topics")
            .and_then(Value::as_array)
            .map(|a| {
                a.iter()
                    .filter_map(Value::as_str)
                    .map(str::to_string)
                    .collect()
            })
            .unwrap_or_default();
        let mut terms: Vec<String> = Vec::new();
        let mut push = |t: &str| {
            if !t.is_empty() {
                terms.push(t.to_string());
                terms.push(t.to_lowercase());
            }
        };
        for d in &pack.defs {
            push(&d.symbol);
        }
        for f in &pack.files {
            for comp in f.path.split('/') {
                push(strip_extension(comp));
            }
        }
        for text in std::iter::once(ask_for.as_str()).chain(topics.iter().map(String::as_str)) {
            terms.extend(words(text));
        }
        let tag = opts
            .tags
            .get(&(slug.to_string(), pin8.to_string()))
            .cloned()
            .unwrap_or_else(|| format!("pack-{slug}-{pin8}"));
        let pack_url = format!("{}/{tag}/{file}", opts.release_base.trim_end_matches('/'));
        out.push(CatalogueEntry {
            slug: slug.to_string(),
            domain: field("cat").to_string(),
            topics,
            ask_for,
            pin_sha: pack.manifest.pin_sha.clone(),
            pin_date: pack.manifest.pin_date.clone(),
            refresh_cadence_days: cadence_days(field("refresh")),
            licence_spdx: pack.manifest.licence_spdx.clone(),
            licence_class: pack.manifest.licence_class,
            pack_bytes: pack.bytes,
            sig_url: format!("{pack_url}.sig"),
            pack_url,
            pack_sha256: pack.sha256,
            dependency_names: Vec::new(),
            quality_grade: None,
            upstream: crate::catalogue::upstream_list(
                pack.manifest
                    .sources
                    .iter()
                    .map(|s| (s.url.as_str(), s.repo.as_str())),
            ),
            term_sketch: crate::sketch::build(terms),
        });
    }
    Ok(out)
}

/// gen.py `suite_median`: relevant-of-5 from the per-query verdicts, or
/// `None` when no query carries a gradable verdict.
fn suite_median(queries: &Value) -> Option<f64> {
    let mut got: Vec<f64> = Vec::new();
    for q in queries.as_array()? {
        let verdict = ["verdict", "grade"]
            .into_iter()
            .filter_map(|k| q.get(k))
            .find(|v| truthy(v));
        let label = match verdict {
            Some(Value::String(s)) => s.clone(),
            Some(v) => v.to_string(),
            None => String::new(),
        };
        if label.contains("excluded") {
            continue;
        }
        got.push(match label.as_str() {
            "pass" | "relevant" => 1.0,
            "partial" => 0.5,
            _ => 0.0,
        });
    }
    if got.is_empty() {
        return None;
    }
    Some(got.iter().sum::<f64>() / got.len() as f64 * 5.0)
}

/// Python truthiness for the `a or b` in gen.py.
fn truthy(v: &Value) -> bool {
    match v {
        Value::Null => false,
        Value::Bool(b) => *b,
        Value::Number(n) => n.as_f64() != Some(0.0),
        Value::String(s) => !s.is_empty(),
        Value::Array(a) => !a.is_empty(),
        Value::Object(o) => !o.is_empty(),
    }
}

/// The members of a verified pack the catalogue needs.
struct PackFacts {
    bytes: u64,
    sha256: String,
    manifest: PackManifest,
    defs: Vec<DefRecord>,
    files: Vec<PackFileEntry>,
}

/// Verify `archive` (sha256 is computed, the `.sig` beside it must verify under
/// `pubkey_hex`) and read `pack.json`, `defs.jsonl` and `files.jsonl` without
/// extracting anything.
fn read_pack(archive: &Path, pubkey_hex: &str) -> Result<PackFacts> {
    let raw = fs::read(archive).with_context(|| format!("read {}", archive.display()))?;
    let mut sig = archive.as_os_str().to_os_string();
    sig.push(".sig");
    let sig = PathBuf::from(sig);
    let sig_hex = fs::read_to_string(&sig).with_context(|| format!("read {}", sig.display()))?;
    verify_bytes(&raw, sig_hex.trim(), pubkey_hex).context("pack signature")?;
    let sha256 = hex(&Sha256::digest(&raw));

    let mut pack_json: Option<Vec<u8>> = None;
    let mut defs_jsonl: Option<Vec<u8>> = None;
    let mut files_jsonl: Option<Vec<u8>> = None;
    let mut tar = tar::Archive::new(zstd::Decoder::new(raw.as_slice()).context("zstd")?);
    for entry in tar.entries().context("read tar")? {
        let mut entry = entry.context("read tar entry")?;
        let path = entry.path()?.to_string_lossy().into_owned();
        let slot = match path.as_str() {
            "pack.json" => &mut pack_json,
            "defs.jsonl" => &mut defs_jsonl,
            "files.jsonl" => &mut files_jsonl,
            _ => continue,
        };
        let mut buf = Vec::new();
        entry.read_to_end(&mut buf)?;
        *slot = Some(buf);
    }
    let pack_json = pack_json.ok_or_else(|| anyhow!("pack.json missing"))?;
    let manifest: PackManifest = serde_json::from_slice(&pack_json).context("parse pack.json")?;
    if manifest.format_version != PACK_FORMAT_VERSION {
        bail!(
            "pack format_version {} (this build writes {PACK_FORMAT_VERSION})",
            manifest.format_version
        );
    }
    Ok(PackFacts {
        bytes: raw.len() as u64,
        sha256,
        manifest,
        defs: parse_jsonl(
            &defs_jsonl.ok_or_else(|| anyhow!("defs.jsonl missing"))?,
            "defs.jsonl",
        )?,
        files: parse_jsonl(
            &files_jsonl.ok_or_else(|| anyhow!("files.jsonl missing"))?,
            "files.jsonl",
        )?,
    })
}

fn parse_jsonl<T: serde::de::DeserializeOwned>(bytes: &[u8], what: &str) -> Result<Vec<T>> {
    let text = std::str::from_utf8(bytes).with_context(|| format!("{what} is not UTF-8"))?;
    text.lines()
        .filter(|l| !l.trim().is_empty())
        .enumerate()
        .map(|(n, l)| serde_json::from_str(l).with_context(|| format!("{what} line {}", n + 1)))
        .collect()
}

/// `lz4frame.c` → `lz4frame`; `lib` → `lib`; `.github` → `.github` (a leading
/// dot is a name, not an extension).
fn strip_extension(comp: &str) -> &str {
    match comp.rfind('.') {
        Some(i) if i > 0 => &comp[..i],
        _ => comp,
    }
}

/// Lower-case words of 3+ ASCII letters.
fn words(text: &str) -> impl Iterator<Item = String> + '_ {
    text.split(|c: char| !c.is_ascii_alphabetic())
        .filter(|w| w.len() >= 3)
        .map(str::to_ascii_lowercase)
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

