            AppendOutcome::AlreadyPresent
        );
        let lock = read_lock(&path).unwrap().unwrap();
        assert_eq!(lock.corpus.len(), 1);
        assert_eq!(lock.lookup("quinn").unwrap().pin_sha, "original0");
